:root{--primary:#1b8168;--on-primary:#fff;--primary-fg:#117b63;--primary-soft:#dcf5ec;--accent-soft:#eaf2ce;--accent-fg:#56701f;
--cream:#f4f8f0;--stage:#edf1ea;--line:#e2eadf;--line-strong:#cbdac7;--paper:#fff;--ink:#1e2e27;--ink-soft:#5c7069;--danger:#b23b3b;--danger-soft:#f6e4e2;--teal-soft:#d9ecec}
*{box-sizing:border-box}
body{margin:0;background:var(--stage);font-family:"Figtree","Segoe UI",system-ui,sans-serif;color:var(--ink)}
.phone{max-width:420px;margin:16px auto;background:var(--cream);border-radius:28px;padding:16px;min-height:760px;box-shadow:0 8px 30px -12px rgba(0,0,0,.2)}
.topbar{display:flex;align-items:center;justify-content:space-between;margin-bottom:14px}
.logo{font-family:"Bricolage Grotesque","Segoe UI",sans-serif;font-weight:800;font-size:20px;color:var(--primary)}
.avatar{width:36px;height:36px;border-radius:50%;background:var(--primary-soft);display:flex;align-items:center;justify-content:center;font-weight:800;color:var(--primary-fg)}
.login{font-size:14px;font-weight:800;color:var(--primary-fg)}
.search{display:flex;align-items:center;gap:8px;min-height:50px;border:2px solid var(--primary);background:var(--paper);border-radius:999px;padding:0 6px 0 16px;margin-bottom:12px}
.search input{flex:1;border:0;outline:0;font-size:16px;background:transparent;color:var(--ink)}
.clear{width:36px;height:36px;border-radius:50%;background:var(--cream);border:0;font-size:16px}
.seg{display:grid;grid-template-columns:1fr 1fr;gap:4px;background:var(--line);border-radius:999px;padding:4px;margin-bottom:10px}
.seg button{min-height:40px;border:0;border-radius:999px;background:transparent;font-weight:800;font-size:15px;color:var(--ink-soft);font-family:inherit}
.seg button.on{background:var(--paper);color:var(--ink);box-shadow:0 2px 8px -2px rgba(42,35,32,.25)}
.seg.small button{min-height:34px;font-size:13px}
.filters{display:flex;gap:6px;overflow-x:auto;margin-bottom:12px}
.chip{flex:none;min-height:36px;border:1px solid var(--line-strong);background:var(--paper);border-radius:999px;padding:0 12px;font-size:13px;font-weight:700;color:var(--ink);display:flex;align-items:center;gap:4px}
.chip.set{background:var(--primary-soft);border-color:var(--primary);color:var(--primary-fg)}
.summary{font-size:14px;color:var(--ink-soft);margin:0 0 10px}
.grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}
.card{position:relative;display:flex;flex-direction:column;border:1px solid var(--line);background:var(--paper);border-radius:16px;padding:10px}
.thumb{aspect-ratio:1;border-radius:12px;background:linear-gradient(135deg,#dfebdc,#d9ecec);display:flex;align-items:center;justify-content:center;font-size:30px}
.dim .thumb{opacity:.6}
.name{margin-top:8px;font-size:13px;font-weight:700;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.cond{font-size:11px;color:var(--ink-soft);margin:2px 0 8px}
.pills{margin-top:auto;display:flex;flex-wrap:wrap;gap:4px}
.pill{font-size:11px;font-weight:800;border-radius:999px;padding:3px 8px}
.pill.gift{background:var(--primary-soft);color:var(--primary-fg)}
.pill.swap{background:var(--accent-soft);color:var(--accent-fg)}
.pill.res{background:var(--line);color:var(--ink-soft)}
.list{list-style:none;margin:0;padding:0;display:flex;flex-direction:column;gap:10px}
.row{display:flex;gap:12px;align-items:flex-start;border:1px solid var(--line);background:var(--paper);border-radius:20px;padding:12px}
.date{flex:none;width:52px;border-radius:14px;background:var(--primary-soft);text-align:center;padding:6px 0;color:var(--primary-fg)}
.date b{display:block;font-family:"Bricolage Grotesque",sans-serif;font-size:22px;line-height:1}
.date span{font-size:11px;font-weight:800;text-transform:uppercase}
.icon{flex:none;width:52px;height:52px;border-radius:14px;display:flex;align-items:center;justify-content:center;font-size:22px}
.icon.grp{background:var(--accent-soft)} .icon.org{background:var(--teal-soft)}
.kind{font-size:10px;font-weight:800;letter-spacing:.04em;text-transform:uppercase;color:var(--ink-soft)}
.title{font-family:"Bricolage Grotesque",sans-serif;font-weight:700;font-size:16px;margin:1px 0}
.sub{font-size:13px;color:var(--ink-soft)}
.desc{font-size:13px;color:var(--ink);margin-top:3px;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.next{font-size:13px;font-weight:800;color:var(--primary-fg);margin-top:4px}
.mine{font-size:10px;font-weight:800;background:var(--primary-soft);color:var(--primary-fg);border-radius:999px;padding:2px 7px;margin-left:4px}
.other{display:flex;align-items:center;justify-content:space-between;margin-top:16px;padding:12px 14px;border-radius:16px;font-size:14px;font-weight:700;color:var(--primary-fg);border:1px solid var(--line);background:var(--paper)}
.other.hl{background:var(--primary);color:var(--on-primary);border-color:var(--primary);font-size:15px}
.empty{border:2px dashed var(--line-strong);border-radius:28px;background:var(--paper);padding:24px;text-align:center}
.empty .ic{width:56px;height:56px;margin:0 auto 10px;border-radius:16px;background:var(--cream);display:flex;align-items:center;justify-content:center;font-size:26px}
.empty h2{font-family:"Bricolage Grotesque",sans-serif;font-size:20px;margin:0 0 6px}
.empty p{font-size:14px;color:var(--ink-soft);margin:0 0 14px}
.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:0 20px;border-radius:999px;background:var(--primary);color:var(--on-primary);font-weight:800;font-size:15px;border:0;text-decoration:none}
.btn.ghost{background:var(--paper);color:var(--primary-fg);border:1px solid var(--line-strong)}
.hint{border-radius:22px;background:var(--paper);border:1px dashed var(--line-strong);padding:20px;font-size:14px;color:var(--ink-soft);text-align:center}
.more{display:block;text-align:center;margin-top:12px;font-size:13px;font-weight:800;color:var(--primary-fg)}
h1.page{font-family:"Bricolage Grotesque",sans-serif;font-size:26px;margin:0 0 14px}
.field{display:flex;flex-direction:column;gap:6px;margin-bottom:12px}
.field label{font-size:13px;font-weight:800}
.input{min-height:48px;border:1px solid var(--line-strong);border-radius:14px;background:var(--paper);padding:10px 14px;font-size:15px;font-family:inherit;color:var(--ink)}
textarea.input{min-height:110px;resize:vertical}
.counter{text-align:right;font-size:12px;color:var(--ink-soft)}
.counter.over{color:var(--danger);font-weight:800}
.input.err{border-color:var(--danger);background:var(--danger-soft)}
.alert{font-size:13px;color:var(--danger);font-weight:700}
.helper{font-size:12px;color:var(--ink-soft)}
.banner{border-radius:16px;background:var(--danger-soft);color:var(--danger);padding:12px 14px;font-size:14px;font-weight:700;margin-bottom:12px}
.gcard{overflow:hidden;border-radius:28px;border:1px solid var(--line);background:var(--paper);margin-bottom:16px}
.gvis{background:var(--primary-soft);padding:20px;display:flex;justify-content:center}
.circle{width:150px;height:150px;border-radius:50%;border:3px dashed var(--primary);position:relative}
.circle i{position:absolute;width:18px;height:18px;border-radius:50%;background:var(--primary)}
.gbody{padding:16px}
.layout{font-size:11px;font-weight:800;text-transform:uppercase;color:var(--ink-soft)}
.gname{font-family:"Bricolage Grotesque",sans-serif;font-size:24px;margin:2px 0 4px}
.gdesc{font-size:14px;line-height:1.5;color:var(--ink);margin:8px 0 6px;white-space:pre-line}
.facts b{font-size:13px;display:block}
.facts span{font-size:13px;color:var(--ink-soft)}
.crumb{font-size:13px;color:var(--primary-fg);font-weight:800;margin-bottom:10px}
.cols{display:flex;gap:18px;flex-wrap:wrap;justify-content:center}
.cols .phone{margin:16px 0}
.cap{text-align:center;font-size:12px;font-weight:800;color:var(--ink-soft);text-transform:uppercase;margin-top:6px}

